import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"কন্ট্রিবিউশন গাইডলাইন (Contribution Guidelines)","description":"","frontmatter":{},"headers":[],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md"}'),i={name:"CONTRIBUTING.md"};function s(r,e,d,c,u,l){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="কন্ট্রিবিউশন-গাইডলাইন-contribution-guidelines" tabindex="-1">কন্ট্রিবিউশন গাইডলাইন (Contribution Guidelines) <a class="header-anchor" href="#কন্ট্রিবিউশন-গাইডলাইন-contribution-guidelines" aria-label="Permalink to &quot;কন্ট্রিবিউশন গাইডলাইন (Contribution Guidelines)&quot;">​</a></h1><p>এই প্রজেক্টে কন্ট্রিবিউট করার জন্য আপনাকে এক্সপার্ট কোডার হতে হবে না। আমরা চাই সবাই এই আর্কিটেকচারাল ডিসকাশনে অংশগ্রহণ করুক।</p><h2 id="নন-কোডারদের-জন্য-markdown-submission" tabindex="-1">নন-কোডারদের জন্য (Markdown Submission) <a class="header-anchor" href="#নন-কোডারদের-জন্য-markdown-submission" aria-label="Permalink to &quot;নন-কোডারদের জন্য (Markdown Submission)&quot;">​</a></h2><p>আপনি যদি শুধু আর্কিটেকচার, পলিসি বা গাইডলাইনে কোনো পরিবর্তন আনতে চান, তবে আপনার কোড জানার প্রয়োজন নেই।</p><p>১. প্রজেক্টের যেকোনো <code>.md</code> ফাইল (যেমন: <code>README.md</code>, <code>architecture/01_enterprise_topology.md</code>, ইত্যাদি) ওপেন করুন। ২. গিটহাবে <strong>Edit</strong> (পেন্সিল আইকন) বাটনে ক্লিক করে ফাইলটি এডিট করুন। ৩. লেখা শেষে নিচের <strong>Propose changes</strong> অপশন থেকে একটি <strong>Pull Request (PR)</strong> সাবমিট করুন। ৪. আপনার পরিবর্তনগুলো আমাদের অ্যাডমিন রিভিউ করে মার্জ করে দেবে এবং সাইটে তা সরাসরি আপডেট হয়ে যাবে!</p><h2 id="কোডারদের-জন্য-website-and-automation" tabindex="-1">কোডারদের জন্য (Website and Automation) <a class="header-anchor" href="#কোডারদের-জন্য-website-and-automation" aria-label="Permalink to &quot;কোডারদের জন্য (Website and Automation)&quot;">​</a></h2><p>আপনি যদি এই ল্যান্ডিং পেজ (VitePress) বা এর থিম/প্লাগইনে কোনো কন্ট্রিবিউশন করতে চান:</p><p>১. রিপোজিটরিটি ফর্ক (Fork) করুন এবং আপনার লোকাল মেশিনে ক্লোন করুন। ২. ডিপেন্ডেন্সি ইন্সটল করতে <code>npm install</code> রান করুন। ৩. ডেভেলপমেন্ট সার্ভার চালু করতে <code>npm run docs:dev</code> রান করুন। ৪. আপনার পরিবর্তনগুলো (<code>.vitepress/</code> বা অন্যান্য ফোল্ডারে) করে PR সাবমিট করুন।</p><h2 id="ডিসকাশন-পোর্টাল" tabindex="-1">ডিসকাশন পোর্টাল <a class="header-anchor" href="#ডিসকাশন-পোর্টাল" aria-label="Permalink to &quot;ডিসকাশন পোর্টাল&quot;">​</a></h2><p>যেকোনো আর্কিটেকচারাল সিদ্ধান্ত নিয়ে প্রশ্ন থাকলে সরাসরি গিটহাব <strong>Discussions</strong> এ যান অথবা ওয়েবসাইটের পেজের নিচে থাকা কমেন্ট বক্সে (Giscus) আপনার মতামত জানান।</p>',10)])])}const h=o(i,[["render",s]]);export{m as __pageData,h as default};
